/* crosswalk cards, r07. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7b"]=[{"q":"For any statement P, P ∨ ¬P. What is the pattern called on the ladder?","a":"the either-way principle","w":["the remaining-option technique","not-not-in","the clash technique"],"why":"An or with no side in hand, named in 1f and laid out here."},
 {"q":"P ∨ ¬P for every statement P. What is its accepted name?","a":"the law of excluded middle","w":["the law of non-contradiction","the double-negation law","the law of cases"],"why":"Of a statement and its denial one is so; a third, a middle, is excluded."},
 {"q":"A column assumes ¬(P ∨ ¬P), refutes P, adds an option, clashes. What does it end on?","a":"¬¬(P ∨ ¬P), by either-way-unrefuted","w":["P ∨ ¬P, by either-way","¬P, by refute","⊥, by clash"],"why":"Denying the principle collapses, but the column stops at a double negative."},
 {"q":"From P ∨ ¬P and ¬¬P, a line writes P. What licenses it?","a":"the remaining-option technique","w":["not-not-in","add an option","either-way-unrefuted"],"why":"The case ¬P clashes with ¬¬P; only P survives."},
 {"q":"From ¬¬Q ⇒ Q for every Q, a column reaches P ∨ ¬P. Which Q does it use?","a":"P ∨ ¬P itself","w":["P","¬P","¬¬P"],"why":"Either-way-unrefuted gives ¬¬(P ∨ ¬P); carry the if through at that statement."},
 {"q":"¬¬P ⇒ P holds for this one P, so P ∨ ¬P. What is wrong?","a":"it needs not-not out at P ∨ ¬P, not at P","w":["¬¬P ⇒ P never holds","P ∨ ¬P is not a statement","nothing: the two are the same"],"why":"The fork world has not-not out at P and the principle failing there."},
 {"q":"Two stages, now and later; P established later only. Does P ∨ ¬P hold at now?","a":"no: neither side holds at now","w":["yes: P holds later","yes: ¬P holds at now","no: ¬¬P fails at now"],"why":"¬P at now needs P at no stage after now, but P holds later."},
 {"q":"Same world: P established later only. Does ¬¬P hold at now?","a":"yes: ¬P holds at no stage","w":["no: P is not established now","no: ¬P holds at now","yes: P holds at now"],"why":"¬P fails at later and at now, so ¬¬P holds at now while P does not."},
 {"q":"A world of stages where P ∨ ¬P fails. What does it show?","a":"rung 1’s moves cannot prove the principle","w":["the principle is false","the principle can be refuted","P is not a statement"],"why":"Every rung 1 move keeps the reading, so a proof would hold there."},
 {"q":"Every or a proof uses was given, added as an option, or earned without either-way. What is the proof?","a":"constructive","w":["classical","settled","by contradiction"],"why":"A proof that cites either-way is classical."},
 {"q":"A proof by cases on an unsettled P reaches “there is a thing with this property”. What may it lack?","a":"an address: which thing","w":["a clash","a hypothesis","a last line"],"why":"Nobody may know which case holds, so nobody may know which thing."},
 {"q":"“This sentence is false.” Does either-way say it is so or not so?","a":"no: it is not a statement","w":["yes: either-way covers every sentence","yes: it is false","no: it breaks the principle"],"why":"0a: it is not a statement, so the principle says nothing of it."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7c"]=[{"q":"P ∨ ¬P proved by a column that never cites either-way. What is P?","a":"decidable","w":["classical","true","finite"],"why":"Settled, made exact; decidable is the accepted name."},
 {"q":"P and Q are decidable. Is P ⇒ Q decidable?","a":"yes, by settled-join","w":["no: an if needs either-way","only when P is so","only by finite-search"],"why":"Cases on P and Q: ¬P or Q gives the if; P with ¬Q refutes it."},
 {"q":"Y has n members and φ is decidable on Y. What gives ∃x ∈ Y φ(x) ∨ ¬∃x ∈ Y φ(x)?","a":"finite-search","w":["settled-join","either-way","bounded-some alone"],"why":"An induction on n leads one member out and checks it at each step."},
 {"q":"In finite-search’s step, a line splits x = b ∨ x ≠ b. What licenses it?","a":"finite-is-settled","w":["either-way","settled-join","the remaining-option technique"],"why":"Sameness inside a finite set is decidable (4j)."},
 {"q":"{x ∈ 1 : P}. What is this set named?","a":"⟦P⟧, the mark of P","w":["the row of P","the support of P","the case of P"],"why":"A part of 1 whose only possible member is 0."},
 {"q":"For an undecided P, does finite-search apply to ⟦P⟧?","a":"no: nobody can match it with a number","w":["yes: it is a part of 1","yes: it has at most one member","no: P is not a condition"],"why":"Small is not finite: an undecided condition hides in its description."},
 {"q":"Every even number from 4 up to 4 · 10¹⁸ passes. So every even number passes. What is wrong?","a":"generalising from the cases looked at","w":["the check used either-way","the bounded statement is not decidable","nothing: the check is long enough"],"why":"Finite-search settles the bounded statement only."},
 {"q":"40 · 40 + 40 + 41 = 41 · 41. What does this settle about “n · n + n + 41 is always prime”?","a":"false, by a counterexample","w":["true, by a look","decidable, by finite-search","nothing: one case is not enough"],"why":"One counterexample settles an endless every false."},
 {"q":"Is “p is prime” decidable?","a":"yes: bounded-some searches the divisors up to p","w":["no: there are endlessly many primes","only by either-way","only for p below 10"],"why":"Bounded-some is finite-search over S(m)."},
 {"q":"Each case of “every even number above 2 is a sum of two primes” is decidable. Is the endless every known to be?","a":"no: no look over ℕ ever ends","w":["yes: by finite-search","yes: by settled-join","yes: each case passes"],"why":"Finite-search needs n members; the evens never end."},
 {"q":"{x ∈ 3 : x = 0 ∧ G}, with G an undecided statement. Why does finite-search fail?","a":"the condition is not decidable at 0","w":["the set has no number of members","3 is too large","the condition is not a statement"],"why":"Three members, but at 0 the condition is G."},
 {"q":"Every even number past 2 is a sum of two primes: checked far out, proved for none. What is it called?","a":"the even-sum guess (Goldbach's)","w":["the maximal-member principle (Zorn's lemma)","the row-step technique (Pascal's rule)","the plus-only combination technique (Bézout's)"],"why":"The page names it the even-sum guess, and gives the accepted name in brackets: Goldbach's."},
 {"q":"Every counting number is a sum of at most four squares, as 7 = 4 + 1 + 1 + 1. What is it called?","a":"the four-squares technique (Lagrange's)","w":["the even-sum guess (Goldbach's)","the maximal-member principle (Zorn's lemma)","the row-step technique (Pascal's rule)"],"why":"The page names it the four-squares technique, and gives the accepted name in brackets: Lagrange's."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7d"]=[{"q":"U = {x ∈ 2 : x = 0 ∨ P}. What licenses U as a set, for any statement P?","a":"Separation: a condition may mention P","w":["the choice axiom","Pairing","finite-choice"],"why":"Separation is laid down for any condition."},
 {"q":"U = {x ∈ 2 : x = 0 ∨ P} and V = {x ∈ 2 : x = 1 ∨ P}, and P holds. What are U and V?","a":"both 2: the same set","w":["{0} and {1}","{0} and 2","∅ and 2"],"why":"With P each condition holds of every member of 2; same-members."},
 {"q":"Same U and V, and ¬P. What are they?","a":"{0} and {1}: two different sets","w":["both 2","both {0}","∅ and {1}"],"why":"Each keeps only the member it keeps for certain."},
 {"q":"What gives a choice function for {U, V}?","a":"the choice axiom","w":["finite-choice","least-chooses","two calls, one for each"],"why":"{U, V} has 1 or 2 members by P’s question, so finite-choice cannot count it."},
 {"q":"From U = V, a line writes c(U) = c(V). What gives it?","a":"self-sameness, then the swap axiom","w":["same-members","the choice axiom","settled-order"],"why":"One input, one output: a function treats equal sets alike."},
 {"q":"Call u ∈ U, call v ∈ V, then go on. What fails?","a":"no line gives u = v from U = V","w":["U has no member","the calls need the axiom","u and v are not numbers"],"why":"Two calls have no line between them; a function does."},
 {"q":"u = c(U), v = c(V). What licenses u = v ∨ u ≠ v?","a":"settled-order: u and v are numbers","w":["either-way","the choice axiom","finite-is-settled"],"why":"Members of 2 are numbers (ℕ-is-transitive), so sameness is decidable."},
 {"q":"In the case u ≠ v, what does the column reach?","a":"¬P","w":["P","U = V","0 = 1"],"why":"P would make U = V, so c(U) = c(V): clash."},
 {"q":"In the case u = v, with u = 0 and v = 1, what happens?","a":"0 = 1 clashes, so P","w":["¬P by refute","U = V by same-members","u ≠ v"],"why":"Both picks kept for certain is impossible, so one was kept because P holds."},
 {"q":"With the choice axiom, every statement is so or not so. What technique is that?","a":"choice-gives-either-way","w":["either-way-unrefuted","finite-search","either-way-gives-not-not-out"],"why":"The first proof on the ladder that leans on the choice axiom."},
 {"q":"A claim believed but not yet proved, like the even-sum guess (Goldbach's). What is the accepted word?","a":"a conjecture","w":["a technique","an axiom","a counterexample"],"why":"The page gives conjecture for an open guess."},
 {"q":"Either-way holds, so choice holds. What is wrong?","a":"the road runs one way: the 1963 world has either-way and no choice","w":["either-way is not proved","choice gives either-way only for finite sets","nothing: they are the same"],"why":"6d’s 1963 world holds every statement true or false, and choice fails."},
 {"q":"From the choice axiom, P ∨ ¬P for every statement P. What is it called?","a":"the choice-gives-either-way technique (Diaconescu's)","w":["the four-squares technique (Lagrange's)","the even-sum guess (Goldbach's)","the maximal-member principle (Zorn's lemma)"],"why":"The page names it the choice-gives-either-way technique, and gives the accepted name in brackets: Diaconescu's."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7·cb4"]=[{"q":"Every set of numbers with a member has a least member, decidable or not. What technique is that?","a":"least-member-for-any-set","w":["least-member","no-least-no-members","bottom-member"],"why":"No-least-no-members gives the double negative; not-not-out removes it."},
 {"q":"X = {n ∈ ℕ : n = 5 ∨ (n = 2 ∧ P)}, P the even-sum guess (Goldbach's). What is the least member of X?","a":"2 or 5, and nobody can say which","w":["5, since 2 may not be in X","2, since 2 < 5","none: X is not decidable"],"why":"Split on P: if P, 2; if ¬P, 5. It exists with no address."},
 {"q":"Searching up from 0 for the least member of that X. Where does the search stall?","a":"at 2: “is 2 in X?” is P’s question","w":["at 0","at 5","it never starts"],"why":"Least-member searches; least-member-for-any-set does not."},
 {"q":"≤ is a well-order of ℕ. What is its accepted name?","a":"the well-ordering principle for the numbers","w":["the maximal-member principle (Zorn's lemma)","strong induction","the choice axiom"],"why":"6e’s principle, said of ℕ and its own order."},
 {"q":"Prove every number above 1 is a product of primes. “Suppose not; take the least m above 1 that is not.” What shape is that?","a":"take a smallest counterexample","w":["strong induction","descent by cases","finite-search"],"why":"Not-every gives a failure; least-member-for-any-set gives the least."},
 {"q":"A smallest-counterexample proof, turned around by 7f’s test. What is it?","a":"a strong induction","w":["a proof by cases","a finite search","a definition by repeating"],"why":"Strong induction is the same proof with the costume off, and needs no either-way."},
 {"q":"“Suppose some number has the property; then a smaller one does, and so on without end.” What is this old method called?","a":"descent","w":["recursion","finite-search","set induction"],"why":"The numbers cannot go down forever, so no number has it."},
 {"q":"b ∈ a and nothing in b is in a. What is b?","a":"a bottom member of a","w":["the least member of a","a maximal member of a","an upper bound of a"],"why":"b ∩ a = ∅: the bottom form of foundation."},
 {"q":"For a set X of numbers, b ∩ X = ∅ exactly when b is least. What technique is that?","a":"bottom-is-least","w":["bottom-member","least-member-for-any-set","any-two-compare"],"why":"For numbers, x ∈ b means x < b."},
 {"q":"Every set with a member has a bottom member, applied to {x ∈ 2 : x = 1 ∨ P}. What does it give?","a":"P ∨ ¬P, by bottom-gives-either-way","w":["the least member is 1","set induction","¬¬P"],"why":"A bottom of 0 gives P; a bottom of 1 refutes P."},
 {"q":"Least-chooses-for-any-set picks from every collection of non-empty sets of numbers. Does it use the choice axiom?","a":"no: it uses least-member-for-any-set","w":["yes: every pick needs it","yes: for undecided sets","no: it uses finite-choice"],"why":"Either-way came from choice on 7d, but no choice function is asked of the axiom here."},
 {"q":"A line writes “≤ well-orders ℤ”. What is wrong?","a":"{x ∈ ℤ : x < 0} has no least member","w":["ℤ is not decidable","≤ is not a partial order on ℤ","nothing: ℕ-well-ordered covers ℤ"],"why":"ℕ-well-ordered is about ℕ only."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7·cb6"]=[{"q":"6e’s column ends on ¬¬(A is an input of m). What line finishes it here?","a":"not-not-out: A is an input of m","w":["the choice axiom: m(A) ∈ A","bounded-chains: m is maximal","refute: A is not an input"],"why":"With either-way, the gap is one line."},
 {"q":"Chains-give-choice, in full. Which principle does its column cite besides the maximal-member principle (Zorn's lemma)?","a":"either-way, once","w":["the choice axiom, once","neither","finite-choice"],"why":"Not-not-out is the either-way principle; no line calls on Choice."},
 {"q":"x ≼ y ∧ x ≠ y. What is it written, and read?","a":"x ≺ y: x is strictly below y","w":["x ≼ y: x is below y","x ⊀ y: x is not below y","Wₓ: below x"],"why":"Strictly below excludes x = y."},
 {"q":"u ∈ a with x ≺ u for every x in C. What is u to C?","a":"a strict upper bound","w":["an upper bound only","a maximal member","an initial part"],"why":"Above every member of C, and equal to none."},
 {"q":"No member of S is maximal; every chain has an upper bound. What does strict-upper-bounds give?","a":"every chain has a strict upper bound","w":["S has a maximal member","every chain is finite","S is well-ordered"],"why":"An upper bound u is not maximal, so some v is strictly above it."},
 {"q":"f(C) is a strict upper bound of each chain C. Where does f come from?","a":"one use of the choice axiom","w":["strict-upper-bounds alone","a recursion past ℕ","least-member-for-any-set"],"why":"f picks from every set of strict upper bounds at once."},
 {"q":"≼ well-orders W, and each x ∈ W is f(Wₓ). What is W?","a":"conforming","w":["a chain only","a strict upper bound","maximal"],"why":"A run of the climb that kept the technique f at every step."},
 {"q":"W and V are conforming. What does conforming-parts-compare give?","a":"one is an initial part of the other","w":["W = V","W ∪ V is maximal","they share no member"],"why":"Least-difference lines them up, one the beginning of the other."},
 {"q":"U is the union of all conforming parts. What is U?","a":"conforming: the long run, gathered at once","w":["a maximal member","not a chain","a run built step by step"],"why":"Conforming-union: the runs line up, so their union is a run."},
 {"q":"U is conforming and u = f(U). Then U ∪ {u} is conforming. Why the clash?","a":"u ∈ U and u ≺ u","w":["u is maximal","U is not a chain","f(U) is not defined"],"why":"U ∪ {u} ⊆ U as a conforming part, but u is strictly above all of U."},
 {"q":"“Choose higher, and so on, past every number.” What is wrong?","a":"that recursion was never built; the runs are gathered instead","w":["choosing higher needs no axiom","the numbers are not ordered","nothing: the climb stops"],"why":"Choice-gives-chains takes every run that keeps one technique, and their union."},
 {"q":"The union of two climbs that chose differently. Is it a run?","a":"not always: only runs keeping one technique f line up","w":["yes: unions of runs are runs","yes: by bounded-chains","no: unions are never runs"],"why":"Conforming-parts-compare needs one f."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7e"]=[{"q":"A line reads ¬¬P; the next reads P. What move is that?","a":"not-not-out","w":["not-not-in","refute","the remaining-option technique alone"],"why":"Either-way supplies P ∨ ¬P; the side ¬P is refuted by ¬¬P."},
 {"q":"Not-not-out: from ¬¬P, P. What is its accepted name?","a":"double negation elimination","w":["proof by contradiction","excluded middle","the contrapositive"],"why":"Two nots taken off at once."},
 {"q":"¬(P ∧ Q) ⇒ ¬P ∨ ¬Q. What does its column split on?","a":"either-way at P","w":["the remaining-option technique","finite-search","a given or"],"why":"Not-both forward: in the case P, refute Q; in the case ¬P, add an option."},
 {"q":"(¬Q ⇒ ¬P) ⇒ (P ⇒ Q). Which line of its column needs rung 7?","a":"¬¬Q to Q, by not-not-out","w":["assume ¬Q","carry through to ¬P","prove an if"],"why":"Turn-and-deny turned back stops at ¬¬Q without it."},
 {"q":"¬(P ⇒ Q). What does negated-if forward give?","a":"P ∧ ¬Q","w":["¬P ∧ Q","¬P ∨ Q","Q ⇒ P"],"why":"Free-if refutes Q and refutes ¬P; not-not-out gives P."},
 {"q":"¬∀x P(x). What does not-every give?","a":"∃x ¬P(x), with no address","w":["∀x ¬P(x)","¬∃x P(x)","a named x with ¬P(x)"],"why":"The some comes from a refutation and not-not-out, so it names nothing."},
 {"q":"Either-way, so the converse of an if is now a technique. What is wrong?","a":"either-way licenses techniques only; the converse never was one","w":["the converse needs not-not-out too","nothing: every direction is licensed","the converse is the contrapositive"],"why":"Gomez the dog still sinks “if it is an animal, it is a cat”."},
 {"q":"(P ⇒ Q) ∨ (Q ⇒ P). How is it proved?","a":"either-way at Q, and free-if in each case","w":["finite-search on P and Q","not-not-out on P","by the room of laughers"],"why":"Case Q gives P ⇒ Q; case ¬Q gives Q ⇒ P."},
 {"q":"A statement built from letters whose column is all T. What does always-true-lines give?","a":"it can be proved","w":["it is decidable without either-way","it is a definition","it holds at every stage, with no proof"],"why":"Split on each letter by either-way, and work each row with moves."},
 {"q":"A non-empty room: some y with L(y) ⇒ everybody laughs. Which person, in an endless room?","a":"one exists, and nobody may name it","w":["anyone who laughs","the first person listed","someone who is not laughing, found by search"],"why":"Room-of-laughers splits on an undecided every."},
 {"q":"⟦P⟧ for any statement P. What does every-mark-is-a-bit give?","a":"⟦P⟧ = 0 ∨ ⟦P⟧ = 1","w":["⟦P⟧ = 1","⟦P⟧ ⊆ 1 only","⟦P⟧ is decidable"],"why":"Either-way at P: 1 if P, by same-members; 0 if ¬P."},
 {"q":"X has n members. How many members has 𝒫(X), now?","a":"2ⁿ, by all-parts-counted","w":["2ⁿ decidable ones, the rest uncounted","n","n!"],"why":"Either-way makes every part decidable member by member."},
 {"q":"For any P and Q, (P ⇒ Q) ∨ (Q ⇒ P). What is it called?","a":"the one-way-or-the-other technique (Dummett's)","w":["the choice-gives-either-way technique (Diaconescu's)","the four-squares technique (Lagrange's)","the even-sum guess (Goldbach's)"],"why":"The page names it the one-way-or-the-other technique, and gives the accepted name in brackets: Dummett's."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7f"]=[{"q":"“No fraction squares to 2. Suppose p/q does …” then a clash. Which form is this?","a":"a refutation: no rung 7 needed","w":["contradiction proper: ends with not-not-out","a contrapositive","a proof by cases"],"why":"The statement wanted is a denial; the refute writes it at once."},
 {"q":"To prove P, assume ¬P, reach ⊥, write ¬¬P, then P. What is the shape called?","a":"proof by contradiction","w":["refutation","proof by contrapositive","proof by descent"],"why":"Its old name is reductio ad absurdum."},
 {"q":"To prove “every prime above 2 is odd”, a proof supposes every one is even. What is wrong?","a":"not the denial: it is “some prime above 2 is even”","w":["nothing: that is the denial","it should suppose every prime is odd","primes above 2 cannot be supposed"],"why":"Refuting a stronger claim proves nothing."},
 {"q":"Suppose the denial of “if 3 ∣ n · n then 3 ∣ n, for every n”. What do you suppose?","a":"some n has 3 ∣ n · n and 3 ∤ n","w":["every n has 3 ∤ n · n","some n has 3 ∤ n · n and 3 ∣ n","if 3 ∤ n then 3 ∤ n · n"],"why":"Not-every, then negated-if forward: hypothesis held, conclusion fails."},
 {"q":"¬(a < b) for numbers. What rewrite does the supposition use?","a":"b ≤ a, by any-two-compare","w":["b < a","a ≤ b","a ≠ b"],"why":"Exactly one of a < b, a = b, b < a."},
 {"q":"“Suppose the primes are exactly p₁, …, pₖ” is used once, to put a prime divisor of N on the list. What is the proof underneath?","a":"direct: for any list there is a prime not on it","w":["contradiction proper","a contrapositive","a descent"],"why":"Drop the supposition: endless-primes hands you the prime."},
 {"q":"“If p · p is even, p is even. Suppose p · p even and p odd; then p · p is odd.” What is it underneath?","a":"a proof by contrapositive","w":["a direct proof of the converse","contradiction proper","a descent"],"why":"Only the denied conclusion was used; the collision is with the hypothesis."},
 {"q":"(2q − p)² − 2(p − q)² = −(p² − 2q²). What is the step called?","a":"endless-descent","w":["the climb","square-of-a-difference","no-double-square"],"why":"It keeps the size of p² − 2q² and changes its sign."},
 {"q":"A refutation that finds a smaller case from any case. What is its accepted name?","a":"proof by infinite descent","w":["proof by strong induction","proof by contrapositive","proof by cases"],"why":"The smaller cases would go down without end."},
 {"q":"(1, 1) ↦ (3, 2) ↦ (7, 5) ↦ (17, 12) by (p, q) ↦ (p + 2q, p + q). What are 3/2, 7/5, 17/12?","a":"near misses to a square of 2","w":["fractions squaring to 2","prime pairs","descents to 0"],"why":"The gap p² − 2q² stays ±1, never 0."},
 {"q":"x · x = x, x ≠ 1: cancel x, so x = 1, clash. What is wrong?","a":"cancelling x needs x ≠ 0","w":["x · x = x has no answer","the clash proves x = 1","nothing: the proof is sound"],"why":"The collision came from a mistake; the lost answer is 0."},
 {"q":"X ⊄ S(k), so X has a member above k. Does the proof say where to look?","a":"no: it is contradiction proper, with no address","w":["yes: at k + 1","yes: search up from k","no: it is a refutation"],"why":"It shows only that the member’s absence is totally false."}];

(window.LADDER_CARDS=window.LADDER_CARDS||{})["7a"]=[{"q": "A proof ends in “if P then Q”. What does it hand you?", "a": "a move: wherever you have P, write Q", "w": ["one settled claim, used once", "a new axiom", "a table"], "why": "7a1: a proof hands you a move."}, {"q": "What three things make an operator?", "a": "a mark, its condition, its moves", "w": ["a number, a letter, a line", "a start, a step, a stop", "a row, a case, a margin"], "why": "7a2."}, {"q": "A mark has a definition but no proofs yet. What can it do?", "a": "nothing: it means something but does nothing", "w": ["everything its definition says", "only its turned-back moves", "every move of +"], "why": "The proofs give it its moves."}, {"q": "How do you see 0 + (3 + 1) = 1 + 3 once 4f’s proofs are written?", "a": "cite zero on the left and the order, without unpacking", "w": ["unpack both sides to next ones", "count on fingers", "by a table"], "why": "7a3: adding, from definition to operator."}, {"q": "What does rung 7 add?", "a": "one principle: a statement holds or its denial does", "w": ["a new mark with new moves", "a new set of all statements", "a new number beyond the series"], "why": "7a4: the either-way principle of 7b."}, {"q": "Which move does the either-way principle license that rung 1 refused?", "a": "not-not out", "w": ["keep left", "the swap", "add an option"], "why": "New moves for old marks."}, {"q": "A proved if used as a move. Its accepted name?", "a": "a lemma, or a derived rule", "w": ["an axiom laid down", "a case set in", "a variant that falls"], "why": "The cellar."}, {"q": "How has the floor worked, rung by rung?", "a": "a principle laid down, proofs from it, each proof a move", "w": ["moves first, then a principle", "tables, then techniques", "guesses, never proofs"], "why": "7a4."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7g"]=[{"q": "With the either-way principle, how many ways can a statement come out?", "a": "two: true or false", "w": ["three: true, false, or between", "as many as its letters", "one"], "why": "7g1: two values make deduction easy."}, {"q": "Drizzle is between raining and not. Does the either-way principle deny it?", "a": "no: it speaks of statements, not weather", "w": ["yes: there is no drizzle", "yes: drizzle is raining", "no: drizzle is false"], "why": "7g2: the world keeps its middle."}, {"q": "How is “it is raining” made true or false, with drizzle about?", "a": "by deciding what the words claim", "w": ["by the weather alone", "by a vote", "it cannot be"], "why": "A sharper statement can say where the middle is."}, {"q": "For 7g, what is a true or a false?", "a": "more data for a better guess", "w": ["a verdict from on high", "the end of all guessing", "a fact about the world alone"], "why": "7g3: more data for better guesses."}, {"q": "Which moves follow from every statement having a row of 1 or 0?", "a": "cases on any statement, not-not out, contradiction", "w": ["only the swap of equals, nothing more", "only keep left and keep right", "no new moves: the old ones suffice"], "why": "7e, 7f."}, {"q": "Why does the ladder keep showing its guesswork?", "a": "a verdict that hides its guess loses what it knew", "w": ["because guesses are always wrong", "because verdicts are always right", "to make every proof longer"], "why": "7g3."}, {"q": "The either-way principle. Its accepted name?", "a": "the law of excluded middle", "w": ["the law of identity", "the well-ordering principle", "the axiom of choice"], "why": "The cellar."}, {"q": "Logics that keep a middle value. Their accepted name?", "a": "many-valued, or fuzzy, logics", "w": ["modal logics", "classical logics", "choice logics"], "why": "The cellar."}];
